#!/usr/bin/env node
// Local API registry generation needs no deployment credentials or network.
// Foundation server/data-model bindings remain tracked Convex-generated files.
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../ConvexPress-Admin/packages/control-plane/convex");
const generated = path.join(root, "_generated");
for (const file of ["server.js", "server.d.ts", "dataModel.d.ts"]) {
  if (!existsSync(path.join(generated, file))) throw new Error(`Missing tracked Convex foundation binding ${file}`);
}
function modules(directory) {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    if (["_generated", "__tests__", "node_modules"].includes(entry.name)) return [];
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) return modules(file);
    if (!entry.name.endsWith(".ts") || /\.(?:test|spec|d)\.ts$/.test(entry.name) || ["schema.ts", "convex.config.ts"].includes(entry.name)) return [];
    return [path.relative(root, file).split(path.sep).join("/").replace(/\.ts$/, "")];
  }).sort();
}
const paths = modules(root);
const config = readFileSync(path.join(root, "convex.config.ts"), "utf8");
const componentImports = new Map([...config.matchAll(/import\s+(\w+)\s+from\s+["']([^"']+\/convex\.config(?:\.js)?)["']/g)].map((match) => [match[1], match[2].replace(/\/convex\.config(?:\.js)?$/, "/_generated/component.js")]));
const used = [...config.matchAll(/app\.use\((\w+)\);/g)].map((match) => match[1]);
if (used.length !== (config.match(/app\.use\(/g) ?? []).length || used.some((name) => !componentImports.has(name))) throw new Error("Component registration changed; update local binding generation before continuing.");
const header = "/* Generated by scripts/admin/generate-control-bindings.mjs. Do not edit. */\n";
const dts = header + 'import type { ApiFromModules, FilterApi, FunctionReference } from "convex/server";\n' +
  paths.map((name, index) => `import type * as module${index} from "../${name}.js";`).join("\n") +
  "\ndeclare const fullApi: ApiFromModules<{\n" + paths.map((name, index) => `  "${name}": typeof module${index};`).join("\n") +
  '\n}>;\nexport declare const api: FilterApi<typeof fullApi, FunctionReference<any, "public">>;\nexport declare const internal: FilterApi<typeof fullApi, FunctionReference<any, "internal">>;\nexport declare const components: {\n' +
  used.map((name) => `  ${name}: import("${componentImports.get(name)}").ComponentApi<"${name}">;`).join("\n") + "\n};\n";
const js = header + 'import { anyApi, componentsGeneric } from "convex/server";\nexport const api = anyApi;\nexport const internal = anyApi;\nexport const components = componentsGeneric();\n';
for (const [file, contents] of [["api.d.ts", dts], ["api.js", js]]) {
  if (process.argv.includes("--check")) {
    if (readFileSync(path.join(generated, file), "utf8") !== contents) throw new Error(`Stale control-plane binding ${file}; run bun run codegen:control.`);
  } else writeFileSync(path.join(generated, file), contents);
}
console.log(`Control-plane bindings ${process.argv.includes("--check") ? "verified" : "generated"}: ${paths.length} modules, ${used.length} components.`);
